pub async fn pending_server(&self, state: &str) -> Result<Option<String>> {
        let now = super::tokens::now_unix();
        Ok(self
            .pending
            .peek(state)
            .await?
            .filter(|parked| !parked.expired_at(now))
            .map(|parked| parked.server_id))
    }
